files.users.js:
const cache = new Map();
function getUser(db, id) {
  if (!cache.has(id)) cache.set(id, { ...db.users[id] });
  return cache.get(id);
}
function updateUser(db, id, fields) {
  Object.assign(db.users[id], fields);
}
module.exports = { getUser, updateUser };

