const assert = require('assert');
const { getUser, updateUser } = require('../users');
const db = { users: { 1: { name: 'Ann' } } };
getUser(db, 1);
updateUser(db, 1, { name: 'Bea' });
assert.strictEqual(getUser(db, 1).name, 'Bea', 'an update must show on the next getUser');
